## 🗺️ 2. Community-Weltkarte + Passport-Stamps

```tsx
// components/CommunityWorldMap.tsx
'use client'

import { useState } from 'react'
import { ComposableMap, Geographies, Geography, Marker } from 'react-simple-maps'

const GEO_URL = 'https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json'

export interface Stamp {
  id: string
  code: string            // NOR, PRT, JPN …
  country: string
  coordinates: [number, number]
  traveler: string
  note?: string
}

export function CommunityWorldMap({ stamps }: { stamps: Stamp[] }) {
  const [hovered, setHovered] = useState<Stamp | null>(null)

  return (
    <div className="relative rounded-3xl bg-[#1F2B33] p-6 overflow-hidden">
      {/* Candle-Glow */}
      <div className="absolute inset-0" style={{
        background: 'radial-gradient(ellipse at 50% 0%, rgba(201,168,106,0.08), transparent 60%)'
      }} />

      <ComposableMap projectionConfig={{ rotate: [-10, 0, 0], scale: 147 }}>
        <Geographies geography={GEO_URL}>
          {({ geographies }) => geographies.map(geo => (
            <Geography key={geo.rsmKey} geography={geo}
              fill="#243440" stroke="#2E3E4A" strokeWidth={0.3} />
          ))}
        </Geographies>

        {stamps.map((s, i) => (
          <Marker key={s.id} coordinates={s.coordinates}>
            <g className="cursor-pointer"
               onMouseEnter={() => setHovered(s)} onMouseLeave={() => setHovered(null)}>
              {/* Passport-Stempel: gestrichelt, rotiert, Coral-Ink */}
              <g transform={`rotate(${(i % 5) * 8 - 16})`}>
                <circle r={11} fill="rgba(217,122,87,0.14)" stroke="#D97757"
                        strokeWidth={1} strokeDasharray="2 1.5" />
                <circle r={7.5} fill="none" stroke="#D97757" strokeWidth={0.6} />
                <text textAnchor="middle" dy={2.5} fontSize={5}
                      fill="#E8B4A0" fontFamily="monospace">{s.code}</text>
              </g>
            </g>
          </Marker>
        ))}
      </ComposableMap>

      {/* Tooltip */}
      {hovered && (
        <div className="absolute top-4 right-4 bg-[#FAF7F2] rounded-2xl px-5 py-4 shadow-xl max-w-xs">
          <p className="font-serif text-xl text-[#1A3A52]">{hovered.country}</p>
          <p className="font-mono text-xs text-[#D97757] mt-1">gestempelt von {hovered.traveler}</p>
          {hovered.note && <p className="text-sm text-[#1A3A52]/70 mt-2 italic">„{hovered.note}"</p>}
        </div>
      )}

      <p className="mt-4 font-mono text-xs text-[#E8B4A0]/60">
        {stamps.length} Stempel · von der Community hinterlassen
      </p>
    </div>
  )
}
```

**GROQ für Stempel** (`lib/queries.ts` ergänzen):
```ts
export const COMMUNITY_STAMPS = /* groq */ `
  *[_type == "communityPost" && defined(location)] | order(postedAt desc) {
    "id": _id, code: countryCode, country: countryName,
    "coordinates": [location.lng, location.lat],
    "traveler": author->name, note
  }`
```

