## 🎭 3. Mood-Picker + GROQ-Verdrahtung

**API-Route** `app/api/mood/route.ts`:
```ts
import { NextResponse } from 'next/server'
import { client } from '@/lib/sanity'
import { groq } from 'next-sanity'

const MOODS: Record<string, { poetic: string }> = {
  berge:  { poetic: 'Gipfel, Stille, Weite.' },
  kueste: { poetic: 'Salz auf der Haut, Wind im Haar.' },
  stadt:  { poetic: 'Lichter, Gassen, Geschichten.' },
  ruhe:   { poetic: 'Nichts müssen. Alles dürfen.' },
}

export async function GET(req: Request) {
  const mood = new URL(req.url).searchParams.get('mood') ?? ''
  if (!MOODS[mood]) return NextResponse.json({ items: [], poetic: '' }, { status: 400 })

  const items = await client.fetch(groq`
    *[_type == "destination" && $mood in mood] | order(name asc)[0...9] {
      name, country, duration, priceFrom,
      "slug": slug.current,
      "image": mainImage.asset->url
    }`, { mood })

  return NextResponse.json({ items, poetic: MOODS[mood].poetic })
}
```

**Komponente** `components/MoodPicker.tsx`:
```tsx
'use client'

import { useState } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import Image from 'next/image'

const MOODS = [
  { id: 'berge', label: 'Berge' }, { id: 'kueste', label: 'Küste' },
  { id: 'stadt', label: 'Stadt' }, { id: 'ruhe', label: 'Ruhe' },
]

export function MoodPicker() {
  const [mood, setMood] = useState<string | null>(null)
  const [data, setData] = useState<{ items: any[]; poetic: string } | null>(null)

  const pick = async (id: string) => {
    setMood(id)
    const res = await fetch(`/api/mood?mood=${id}`)
    setData(await res.json())
  }

  return (
    <section id="mood" className="py-32 px-6 bg-[#FAF7F2]">
      <div className="max-w-6xl mx-auto">
        <h2 className="font-serif font-light text-5xl text-[#1A3A52] mb-2">Wie fühlt sich dein Herz?</h2>
        <p className="text-[#1A3A52]/60 mb-10">Wähle eine Stimmung — wir wählen den Ort.</p>

        {/* Chips */}
        <div className="flex gap-3 flex-wrap mb-12">
          {MOODS.map(m => (
            <button key={m.id} onClick={() => pick(m.id)}
              className={`px-7 py-3 rounded-full border font-medium transition-all duration-300
                ${mood === m.id
                  ? 'bg-[#D97757] border-[#D97757] text-[#FAF7F2] shadow-lg'
                  : 'border-[#1A3A52]/20 text-[#1A3A52] hover:border-[#D97757] hover:text-[#D97757]'}`}>
              {m.label}
            </button>
          ))}
        </div>

        <AnimatePresence mode="wait">
          {data && (
            <motion.div key={mood} initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.6 }}>
              <p className="font-serif italic text-2xl text-[#D97757] mb-10">„{data.poetic}"</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                {data.items.map((d, i) => (
                  <motion.a key={d.slug} href={`/destinations/${d.slug}`}
                    initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.08 }} className="group">
                    <div className="relative aspect-[4/5] rounded-2xl overflow-hidden mb-3">
                      <Image src={d.image} alt={d.name} fill
                        className="object-cover transition-transform duration-700 group-hover:scale-105" />
                    </div>
                    <h3 className="font-serif text-2xl text-[#1A3A52]">{d.name}</h3>
                    <p className="font-mono text-xs text-[#1A3A52]/50">
                      {d.country} · {d.duration} · ab €{d.priceFrom}
                    </p>
                  </motion.a>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </section>
  )
}
```

