+ export function ScratchCard({ children, height = 240, surface = '#FAF7F2', onReveal }: Props) {

- <div className="absolute inset-0 bg-[#FAF7F2] flex items-center justify-center p-6">
+ <div className="absolute inset-0 flex items-center justify-center p-6" style={{ background: surface }}>

