## 2. 🖼️ OG-Image-Generator — romantische Social-Cards

`app/api/og/route.tsx` — generiert Cards in **beiden Themes**, mit Serif-Quote, Passport-Stempel & Gold-Flecks:

```tsx
import { ImageResponse } from 'next/og'
import type { NextRequest } from 'next/server'

export const runtime = 'edge'

const THEMES = {
  night: { bg: '#141419', ink: '#E8DFD1', accent: '#C9A86A', pin: '#D98E73' },
  cream: { bg: '#FAF7F2', ink: '#1A3A52', accent: '#B87B5E', pin: '#D97757' },
}

const CSS_URL =
  'https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,300;1,400&family=JetBrains+Mono&display=swap'

async function loadFont(style: 'normal' | 'italic', weight: number) {
  const css = await fetch(CSS_URL).then((r) => r.text())
  const re = /\/\* latin \*\/\s*@font-face\s*\{([^}]+)\}/g
  let m: RegExpExecArray | null
  while ((m = re.exec(css))) {
    const b = m[1]
    if (b.includes(`font-style: ${style};`) && b.includes(`font-weight: ${weight};`)) {
      const url = /url\((https:[^)]+)\)/.exec(b)![1]
      return fetch(url).then((r) => r.arrayBuffer())
    }
  }
  throw new Error('font not found')
}

/* deterministische Gold-Flecks */
const FLECKS = Array.from({ length: 26 }, (_, i) => ({
  x: (i * 137) % 1160 + 20,
  y: (i * 89) % 590 + 20,
  o: 0.08 + ((i * 13) % 10) / 60,
  s: 3 + ((i * 7) % 4),
}))

export async function GET(req: NextRequest) {
  const q = req.nextUrl.searchParams
  const T = q.get('theme') === 'cream' ? THEMES.cream : THEMES.night
  const title = (q.get('title') ?? 'Die Welt wartet auf dich.').slice(0, 60)
  const sub = (q.get('sub') ?? 'travel · booking · journal · community').slice(0, 70)
  const stamp = (q.get('stamp') ?? 'VOYA').slice(0, 4).toUpperCase()

  const [regular, italic, mono] = await Promise.all([
    loadFont('normal', 300), loadFont('italic', 400), loadFont('normal', 400),
  ]).then(([a, b, c]) => [
    { name: 'Fraunces', data: a, weight: 300, style: 'normal' as const },
    { name: 'Fraunces', data: b, weight: 400, style: 'italic' as const },
    { name: 'JetBrains Mono', data: c, weight: 400, style: 'normal' as const },
  ])

  return new ImageResponse(
    (
      <div style={{ width: '100%', height: '100%', background: T.bg, display: 'flex', flexDirection: 'column', padding: 56, position: 'relative', fontFamily: 'Fraunces' }}>
        {/* Gold-Flecks */}
        {FLECKS.map((f, i) => (
          <div key={i} style={{ position: 'absolute', left: f.x, top: f.y, width: f.s, height: f.s, borderRadius: '50%', background: T.accent, opacity: f.o }} />
        ))}
        {/* Rahmen */}
        <div style={{ position: 'absolute', inset: 24, border: `1px solid ${T.accent}55` }} />

        {/* Kopf: Brand + Stempel */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <span style={{ fontFamily: 'JetBrains Mono', fontSize: 15, letterSpacing: '0.35em', color: T.accent, textTransform: 'uppercase' }}>
            Voya · {stamp === 'VOYA' ? 'Travel & Community' : 'Passport'}
          </span>
          <div style={{ width: 96, height: 96, borderRadius: '50%', border: `2px dashed ${T.pin}`, display: 'flex', alignItems: 'center', justifyContent: 'center', transform: 'rotate(-8deg)' }}>
            <div style={{ width: 72, height: 72, borderRadius: '50%', border: `1px solid ${T.pin}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <span style={{ fontFamily: 'JetBrains Mono', fontSize: 20, color: T.pin, letterSpacing: '0.15em' }}>{stamp}</span>
            </div>
          </div>
        </div>

        {/* Quote / Title */}
        <div style={{ flex: 1, display: 'flex', alignItems: 'center' }}>
          <p style={{ fontSize: title.length > 34 ? 64 : 80, lineHeight: 1.12, color: T.ink, fontStyle: 'italic', fontWeight: 300, maxWidth: 940 }}>
            {title}
          </p>
        </div>

        {/* Fuß */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 20 }}>
          <div style={{ height: 1, width: 120, background: T.accent }} />
          <span style={{ fontFamily: 'JetBrains Mono', fontSize: 16, color: T.accent }}>{sub}</span>
          <span style={{ fontFamily: 'JetBrains Mono', fontSize: 16, color: `${T.ink}88`, marginLeft: 'auto' }}>voya.travel</span>
        </div>
      </div>
    ),
    {
      width: 1200, height: 630,
      fonts: [regular, italic, mono],
      headers: { 'Cache-Control': 'public, s-maxage=86400, stale-while-revalidate=604800' },
    },
  )
}
```

