// lib/push.ts
import webpush from 'web-push'
import { client } from './sanity'

webpush.setVapidDetails('mailto:hello@voya.travel',
  process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY!, process.env.VAPID_PRIVATE_KEY!)

export async function sendPush(payload: { title: string; body: string; url: string }) {
  const subs = await client.fetch(`*[_type == "pushSubscription"] { _id, sub }`)
  for (const s of subs) {
    try {
      await webpush.sendNotification(JSON.parse(s.sub), JSON.stringify(payload))
    } catch (e: any) {
      if (e.statusCode === 404 || e.statusCode === 410) await client.delete(s._id) // tot → aufräumen
    }
  }
}
