## `hooks/useVoyaPush.ts` (App)

```ts
import { useEffect } from 'react'
import * as Notifications from 'expo-notifications'
import * as Device from 'expo-device'
import { useRouter } from 'expo-router'

const API = process.env.EXPO_PUBLIC_API_URL!

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowBanner: true, shouldShowList: true, shouldPlaySound: true, shouldSetBadge: true,
  }),
})

export function useVoyaPush() {
  const router = useRouter()

  useEffect(() => {
    (async () => {
      if (!Device.isDevice) return
      const { status } = await Notifications.requestPermissionsAsync()
      if (status !== 'granted') return
      const token = (await Notifications.getExpoPushTokenAsync()).data
      await fetch(`${API}/api/push/app-subscribe`, { method: 'POST', body: JSON.stringify({ token }) })
    })()

    // Tap auf Notification → direkt zum Stempel/Artikel
    const sub = Notifications.addNotificationResponseReceivedListener((res) => {
      const url = res.notification.request.content.data?.url as string | undefined
      if (url) router.push(url as never)
    })
    return () => sub.remove()
  }, [router])
}
```
→ In `_layout.tsx` einmal `useVoyaPush()` aufrufen. ✅

