## 🎭 3. Mood-Picker + GROQ-Verdrahtung

**API-Route** `app/api/mood/route.ts`:
```ts
import { NextResponse } from 'next/server'
import { client } from '@/lib/sanity'
import { groq } from 'next-sanity'

const MOODS: Record<string, { poetic: string }> = {
  berge:  { poetic: 'Gipfel, Stille, Weite.' },
  kueste: { poetic: 'Salz auf der Haut, Wind im Haar.' },
  stadt:  { poetic: 'Lichter, Gassen, Geschichten.' },
  ruhe:   { poetic: 'Nichts müssen. Alles dürfen.' },
}

export async function GET(req: Request) {
  const mood = new URL(req.url).searchParams.get('mood') ?? ''
  if (!MOODS[mood]) return NextResponse.json({ items: [], poetic: '' }, { status: 400 })

  const items = await client.fetch(groq`
    *[_type == "destination" && $mood in mood] | order(name asc)[0...9] {
      name, country, duration, priceFrom,
      "slug": slug.current,
      "image": mainImage.asset->url
    }`, { mood })

  return NextResponse.json({ items, poetic: MOODS[mood].poetic })
}
```

