# 🥚 Part 2: Das 404-Easter-Egg

**Konzept:** Night-Design, „Diese Seite ist wandern gegangen." — darunter eine kleine Scratch-Karte (Rubbellos-Feeling). Wer rubbelt, findet den geheimen Stempel **TERRA INCOGNITA · 404** + ein Tolkien-Zitat. Die `ScratchCard` ist generisch wiederverwendbar (z. B. später für Newsletter-Freebies).

## `components/ScratchCard.tsx`

```tsx
'use client'

import { useEffect, useRef, useState } from 'react'

interface Props {
  children: React.ReactNode
  height?: number
}

export function ScratchCard({ children, height = 240 }: Props) {
  const boxRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const last = useRef<{ x: number; y: number } | null>(null)
  const ticks = useRef(0)
  const [done, setDone] = useState(false)

  useEffect(() => {
    const canvas = canvasRef.current, box = boxRef.current
    if (!canvas || !box) return
    const r = box.getBoundingClientRect()
    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    canvas.width = r.width * dpr
    canvas.height = r.height * dpr
    const ctx = canvas.getContext('2d')!
    ctx.scale(dpr, dpr)

    // Folie + Gold-Splitter + Hint
    const g = ctx.createLinearGradient(0, 0, r.width, r.height)
    g.addColorStop(0, '#26262E'); g.addColorStop(1, '#1B1B21')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, r.width, r.height)
    for (let i = 0; i < 140; i++) {
      ctx.fillStyle = `rgba(201,168,106,${Math.random() * 0.25})`
      ctx.beginPath()
      ctx.arc(Math.random() * r.width, Math.random() * r.height, Math.random() * 1.4, 0, Math.PI * 2)
      ctx.fill()
    }
    ctx.fillStyle = 'rgba(201,168,106,0.6)'
    ctx.font = '12px "JetBrains Mono", monospace'
    ctx.textAlign = 'center'
    ctx.fillText('✦  scratch me  ✦', r.width / 2, r.height / 2)
  }, [])

  const dot = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
    ctx.globalCompositeOperation = 'destination-out'
    const grad = ctx.createRadialGradient(x, y, 0, x, y, 34)
    grad.addColorStop(0, 'rgba(0,0,0,1)')
    grad.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = grad
    ctx.beginPath(); ctx.arc(x, y, 34, 0, Math.PI * 2); ctx.fill()
  }

  const sample = () => {
    const c = canvasRef.current!
    const d = c.getContext('2d')!.getImageData(0, 0, c.width, c.height).data
    let clear = 0, total = 0
    for (let i = 3; i < d.length; i += 96) { total++; if (d[i] < 64) clear++ }
    return clear / total
  }

  const pos = (e: React.PointerEvent) => {
    const r = canvasRef.current!.getBoundingClientRect()
    return { x: e.clientX - r.left, y: e.clientY - r.top }
  }

  const onMove = (e: React.PointerEvent) => {
    if (!last.current || done) return
    const ctx = canvasRef.current!.getContext('2d')!
    const p = pos(e)
    const dist = Math.hypot(p.x - last.current.x, p.y - last.current.y)
    const steps = Math.max(1, Math.floor(dist / 5))
    for (let i = 0; i <= steps; i++) {
      dot(ctx, last.current.x + ((p.x - last.current.x) * i) / steps,
               last.current.y + ((p.y - last.current.y) * i) / steps)
    }
    last.current = p
    if (++ticks.current % 12 === 0 && sample() >= 0.45) setDone(true)
  }

  return (
    <div ref={boxRef} className="relative rounded-2xl overflow-hidden select-none" style={{ height }}>
      {/* Verborgener Schatz */}
      <div className="absolute inset-0 bg-[#FAF7F2] flex items-center justify-center p-6">
        {children}
      </div>

      {/* Folie */}
      <canvas
        ref={canvasRef}
        onPointerDown={(e) => { (e.target as HTMLElement).setPointerCapture(e.pointerId); last.current = pos(e) }}
        onPointerMove={onMove}
        onPointerUp={() => (last.current = null)}
        onPointerLeave={() => (last.current = null)}
        className={`absolute inset-0 w-full h-full touch-none cursor-crosshair transition-opacity duration-1000
          ${done ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}
      />
    </div>
  )
}
