'use client'

import { useRef, useState } from 'react'
import { motion, useScroll, useMotionValueEvent } from 'framer-motion'
import { ComposableMap, Geographies, Geography, Marker } from 'react-simple-maps'

const GEO_URL = 'https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json'

/* ── Paletten: Night (Gold) & Cream (Ocean/Coral) ── */
const PALETTES = {
  night: {
    bg: '#141419', base: '#232329', stroke: '#141419',
    reveal: '#C9A86A', pin: '#D98E73',
    text: '#E8DFD1', sub: '#C9A86A',
    line: 'rgba(201,168,106,0.4)',
    glow: 'radial-gradient(ellipse at 50% 42%, rgba(201,168,106,0.10), transparent 60%)',
    muted: 'rgba(232,223,209,0.5)',
  },
  cream: {
    bg: '#FAF7F2', base: '#E7DCC9', stroke: '#FAF7F2',
    reveal: '#1A3A52', pin: '#D97757',
    text: '#1A3A52', sub: '#B87B5E',
    line: 'rgba(26,58,82,0.35)',
    glow: 'radial-gradient(ellipse at 50% 42%, rgba(217,122,87,0.08), transparent 60%)',
    muted: 'rgba(26,58,82,0.5)',
  },
} as const

/* ── Länder, die beim Scrollen aufglühen (ISO-ID → Schwelle) ── */
const REVEAL: Record<string, number> = {
  '578': 0.10, '620': 0.18, '250': 0.25, '504': 0.38, '380': 0.45,
  '764': 0.58, '604': 0.65, '392': 0.78, '554': 0.85, '484': 0.92,
}

/* ── Pins: links = Wörter, rechts = Gerichte/Rezept-Anfänge ── */
type Pin = {
  at: number
  top: string
  coords: [number, number]
  side: 'left' | 'right'
  label: string
  sub: string
}

const PINS: Pin[] = [
  { at: 0.10, top: '16%', coords: [10.7, 59.9],  side: 'left',  label: 'home',          sub: 'Norwegen' },
  { at: 0.18, top: '24%', coords: [-9.1, 38.7],  side: 'right', label: 'Pastel de Nata', sub: 'Zimt auf warmer Haut …' },
  { at: 0.25, top: '34%', coords: [2.35, 48.85], side: 'left',  label: 'love',           sub: 'Frankreich' },
  { at: 0.38, top: '42%', coords: [-7.98, 31.6], side: 'right', label: 'Tagine',         sub: 'Safran, Datteln, Dampf …' },
  { at: 0.45, top: '52%', coords: [12.5, 41.9],  side: 'left',  label: 'romantic',       sub: 'Italien' },
  { at: 0.58, top: '60%', coords: [100.5, 13.7], side: 'right', label: 'Khao Soi',       sub: 'Kokos & knusprige Nudeln …' },
  { at: 0.65, top: '70%', coords: [-77, -12.05], side: 'left',  label: 'best experience', sub: 'Peru' },
  { at: 0.78, top: '78%', coords: [139.7, 35.7], side: 'right', label: 'Ramen',          sub: 'Brühe wie Regen auf Asphalt …' },
  { at: 0.85, top: '86%', coords: [174.8, -41.3],side: 'left',  label: 'cool waves',     sub: 'Neuseeland' },
  { at: 0.92, top: '90%', coords: [-99.1, 19.4], side: 'right', label: 'Tacos al Pastor', sub: 'Ananas über offener Flamme …' },
]

export function WorldReveal({ variant = 'night' }: { variant?: keyof typeof PALETTES }) {
  const C = PALETTES[variant]
  const ref = useRef<HTMLElement>(null)
  const [p, setP] = useState(0)

  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] })
  useMotionValueEvent(scrollYProgress, 'change', (v) => {
    const r = Math.round(v * 100) / 100
    setP((prev) => (prev === r ? prev : r))
  })

  return (
    <section ref={ref} style={{ height: '350vh', background: C.bg }}>
      <div className="sticky top-0 h-screen overflow-hidden">
        <div className="absolute inset-0" style={{ background: C.glow }} />

        {/* ── Karte: ruhig in der Mitte ── */}
        <div className="absolute inset-0 flex items-center justify-center opacity-95">
          <ComposableMap projectionConfig={{ scale: 150 }}>
            <Geographies geography={GEO_URL}>
              {({ geographies }) =>
                geographies.map((geo) => {
                  const t = REVEAL[geo.id as string]
                  const on = t !== undefined && p >= t
                  return (
                    <Geography
                      key={geo.rsmKey}
                      geography={geo}
                      fill={on ? C.reveal : C.base}
                      stroke={C.stroke}
                      strokeWidth={0.4}
                      style={{ outline: 'none', transition: 'fill 900ms ease' }}
                    />
                  )
                })
              }
            </Geographies>

            {PINS.map((pin) => (
              <Marker key={pin.label} coordinates={pin.coords}>
                <circle r={2.6} fill={C.pin}
                  opacity={p >= pin.at ? 0.95 : 0}
                  style={{ transition: 'opacity 600ms ease' }} />
                <circle r={6} fill="none" stroke={C.pin} strokeWidth={0.7} strokeDasharray="2 2"
                  opacity={p >= pin.at ? 0.6 : 0}
                  style={{ transition: 'opacity 600ms ease' }} />
              </Marker>
            ))}
          </ComposableMap>
        </div>

        {/* ── Linker Rand: Wörter ── */}
        {PINS.filter((x) => x.side === 'left').map((pin) => (
          <motion.div
            key={pin.label}
            className="absolute left-5 md:left-8 hidden sm:flex items-center gap-3 pointer-events-none"
            style={{ top: pin.top }}
            initial={false}
            animate={{ opacity: p >= pin.at ? 1 : 0, x: p >= pin.at ? 0 : -28 }}
            transition={{ duration: 0.8, ease: 'easeOut' }}
          >
            <div>
              <span className="font-serif italic text-xl md:text-2xl" style={{ color: C.text }}>
                {pin.label}
              </span>
              <span className="block font-mono text-[10px] tracking-widest uppercase" style={{ color: C.muted }}>
                {pin.sub}
              </span>
            </div>
            <span className="h-px w-12 md:w-20"
              style={{ background: `linear-gradient(to right, ${C.line}, transparent)` }} />
          </motion.div>
        ))}

        {/* ── Rechter Rand: Gerichte & Rezept-Anfänge ── */}
        {PINS.filter((x) => x.side === 'right').map((pin) => (
          <motion.div
            key={pin.label}
            className="absolute right-5 md:right-8 hidden sm:flex items-center gap-3 pointer-events-none"
            style={{ top: pin.top }}
            initial={false}
            animate={{ opacity: p >= pin.at ? 1 : 0, x: p >= pin.at ? 0 : 28 }}
            transition={{ duration: 0.8, ease: 'easeOut' }}
          >
            <span className="h-px w-12 md:w-20"
              style={{ background: `linear-gradient(to left, ${C.line}, transparent)` }} />
            <div className="text-right">
              <span className="font-serif text-lg md:text-xl" style={{ color: C.text }}>
                {pin.label}
              </span>
              <span className="block font-serif italic text-xs md:text-sm" style={{ color: C.sub }}>
                {pin.sub}
              </span>
            </div>
          </motion.div>
        ))}

        {/* ── Mobile: Chips statt Ränder ── */}
        <div className="sm:hidden absolute inset-x-3 bottom-28 flex flex-wrap gap-2 justify-center">
          {PINS.map((pin) => (
            <span key={pin.label}
              className="px-3 py-1 rounded-full border font-mono text-[10px]"
              style={{
                borderColor: C.line, color: C.text,
                opacity: p >= pin.at ? 1 : 0.15, transition: 'opacity 500ms',
              }}>
              {pin.label}
            </span>
          ))}
        </div>

        {/* ── Content: ruhig, zentriert, unten ── */}
        <div className="absolute inset-x-0 bottom-10 text-center pointer-events-none px-6">
          <h2 className="font-serif font-light text-3xl md:text-5xl" style={{ color: C.text }}>
            Die Welt öffnet sich, <span className="italic">Stück für Stück.</span>
          </h2>
          <p className="mt-3 font-mono text-[10px] tracking-[0.3em] uppercase" style={{ color: C.muted }}>
            scroll · {Math.round(p * 100)} % entdeckt
          </p>
        </div>
      </div>
    </section>
  )
}
