## 🌓 Theme-Switch (Night ↔ Cream)

```tsx
// components/ThemeProvider.tsx
'use client'
import { createContext, useContext, useEffect, useState } from 'react'

type Theme = 'night' | 'cream'
const Ctx = createContext<{ theme: Theme; toggle: () => void }>({ theme: 'night', toggle: () => {} })
export const useTheme = () => useContext(Ctx)

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<Theme>('night')
  useEffect(() => {
    const saved = localStorage.getItem('voya-theme') as Theme | null
    if (saved) setTheme(saved)
  }, [])
  const toggle = () =>
    setTheme((t) => {
      const next = t === 'night' ? 'cream' : 'night'
      localStorage.setItem('voya-theme', next)
      return next
    })
  return <Ctx.Provider value={{ theme, toggle }}>{children}</Ctx.Provider>
}
