// app/api/newsletter/subscribe/route.ts
import { NextResponse } from 'next/server'
import { client } from '@/lib/sanity'
import { resend, FROM } from '@/lib/resend'

export async function POST(req: Request) {
  const { email } = await req.json()
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return NextResponse.json({ ok: false }, { status: 400 })

  const id = `subscriber-${Buffer.from(email.toLowerCase()).toString('hex').slice(0, 24)}`
  await client.createIfNotExists({ _id: id, _type: 'subscriber', email: email.toLowerCase(), confirmed: true })

  await resend.emails.send({
    from: FROM, to: email, subject: 'Willkommen an Bord ✦',
    html: `<div style="font-family:Georgia,serif;background:#FAF7F2;padding:48px;text-align:center">
      <h1 style="font-weight:300;color:#1A3A52">Schön, dass du da bist.</h1>
      <p style="color:#1A3A52;opacity:.7">Der nächste Voya Letter erreicht dich Donnerstag, 8 Uhr.</p>
      <p style="color:#C9A86A">✦  ✦</p></div>`,
  })
  return NextResponse.json({ ok: true })
}
