```ts
// app/api/newsletter/send/route.ts — geschützt, via Cron/Manuell
import { NextResponse } from 'next/server'
import { render } from '@react-email/render'
import { client } from '@/lib/sanity'
import { resend, FROM } from '@/lib/resend'
import { VoyaLetter, type LetterData } from '@/emails/VoyaLetter'

export async function POST(req: Request) {
  if (req.headers.get('x-newsletter-secret') !== process.env.NEWSLETTER_SECRET)
    return new Response('Unauthorized', { status: 401 })

  const data: LetterData = await req.json()   // Issue-Daten
  const subs = await client.fetch(`*[_type == "subscriber" && confirmed] { email }`)
  const html = await render(<VoyaLetter {...data} />)

  let sent = 0
  for (const s of subs) {   // Resend-Rate-Limit respektieren
    await resend.emails.send({ from: FROM, to: s.email, subject: `Voya Letter #${data.issue} — ${data.story.title}`, html })
    sent++
    await new Promise((r) => setTimeout(r, 500))
  }
  return NextResponse.json({ sent })
}
