// components/LocaleProvider.tsx
'use client'
import { createContext, useContext, useEffect, useState } from 'react'
import { defaultLocale, dictionaries, type Locale } from '@/lib/i18n/dictionaries'

const Ctx = createContext<{ locale: Locale; setLocale: (l: Locale) => void; t: (p: string) => string }>({
  locale: defaultLocale, setLocale: () => {}, t: (p) => p,
})
export const useLocale = () => useContext(Ctx)

export function LocaleProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocale] = useState<Locale>(defaultLocale)

  useEffect(() => {
    const saved = document.cookie.match(/voya-locale=(\w+)/)?.[1] as Locale | undefined
    if (saved) setLocale(saved)
    else if (navigator.language.startsWith('en')) setLocale('en')
  }, [])

  const set = (l: Locale) => {
    document.cookie = `voya-locale=${l}; path=/; max-age=31536000`
    setLocale(l)
  }

  const t = (path: string) => {
    const v = path.split('.').reduce<any>((o, k) => o?.[k], dictionaries[locale])
    return typeof v === 'string' ? v : path
  }

  return <Ctx.Provider value={{ locale, setLocale: set, t }}>{children}</Ctx.Provider>
}

export function LocaleToggle() {
  const { locale, setLocale } = useLocale()
  return (
    <div className="flex rounded-full border border-current/20 p-0.5 font-mono text-[10px]">
      {(['de', 'en'] as const).map((l) => (
        <button key={l} onClick={() => setLocale(l)}
          className={`px-2.5 py-1 rounded-full uppercase tracking-widest transition-colors
            ${locale === l ? 'bg-[#C9A86A] text-[#141419]' : 'opacity-50 hover:opacity-100'}`}>
          {l}
        </button>
      ))}
    </div>
  )
}
```

