## Offline-Speichern + Regal

```tsx
// components/SaveOffline.tsx
'use client'
import { useEffect, useState } from 'react'

const CACHE = 'voya-offline'
const LIST = 'voya-offline-list'

export function SaveOffline({ slug, images = [] }: { slug: string; images?: string[] }) {
  const [saved, setSaved] = useState(false)

  useEffect(() => {
    if ('caches' in window) caches.match(`/journal/${slug}`).then((r) => setSaved(!!r))
  }, [slug])

  const toggle = async () => {
    const cache = await caches.open(CACHE)
    if (saved) {
      await cache.delete(`/journal/${slug}`)
      await Promise.all(images.map((i) => cache.delete(i)))
    } else {
      await cache.addAll([`/journal/${slug}`, ...images])
    }
    const list: string[] = JSON.parse(localStorage.getItem(LIST) ?? '[]')
    localStorage.setItem(LIST, JSON.stringify(saved ? list.filter((s) => s !== slug) : [...new Set([...list, slug])]))
    setSaved(!saved)
  }

  return (
    <button onClick={toggle}
      className={`flex items-center gap-2 px-4 py-2 rounded-full border font-mono text-xs transition-colors
        ${saved ? 'border-[#D97757] text-[#D97757]' : 'border-[#1A3A52]/20 text-[#1A3A52]/60 hover:border-[#D97757] hover:text-[#D97757]'}`}>
      {saved ? '🔖 offline gespeichert' : '🔖 für offline merken'}
    </button>
  )
}

export function OfflineShelf() {
  const [slugs, setSlugs] = useState<string[]>([])
  useEffect(() => setSlugs(JSON.parse(localStorage.getItem(LIST) ?? '[]')), [])
  if (!slugs.length) return null
  return (
    <div className="rounded-2xl bg-[#E8DFD1]/50 p-6">
      <p className="font-mono text-xs tracking-widest uppercase text-[#B87B5E] mb-4">Dein Offline-Regal ✈</p>
      <ul className="space-y-2">
        {slugs.map((s) => (
          <li key={s}>
            <a href={`/journal/${s}`} className="font-serif text-lg text-[#1A3A52] hover:text-[#D97757] transition-colors">
              {s.replace(/-/g, ' ')}
            </a>
          </li>
        ))}
      </ul>
    </div>
  )
}
```

**Verhalten:** Besuchte Artikel & Sanity-Bilder cachen automatisch (SW), bewusste Saves landen im „Offline-Regal" — perfekt für Flug & Funkloch. 🛫

