import { NextResponse } from 'next/server'
import { stripe } from '@/lib/stripe'
import { STAYS } from '@/lib/stays'

export const runtime = 'nodejs'
const BASE = process.env.NEXT_PUBLIC_BASE_URL!

export async function POST(req: Request) {
  const { destination, slug, stayId, checkIn, checkOut, nights, email } = await req.json()

  const stay = STAYS.find((s) => s.id === stayId)
  if (!stay || !nights || nights < 1 || nights > 60 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email ?? ''))
    return NextResponse.json({ error: 'invalid' }, { status: 400 })

  const session = await stripe.checkout.sessions.create({
    mode: 'payment',
    customer_email: email,
    line_items: [{
      price_data: {
        currency: 'eur',
        product_data: { name: `Voya · ${destination} — ${stay.name}` },
        unit_amount: stay.price * nights * 100,
      },
      quantity: 1,
    }],
    metadata: { destination, slug, stayId, checkIn, checkOut, nights: String(nights) },
    success_url: `${BASE}/booking/success?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${BASE}/destinations/${slug}?canceled=1`,
  })

  return NextResponse.json({ url: session.url })
}
```

## `app/api/webhooks/stripe/route.ts`

```ts
import { NextResponse } from 'next/server'
import { stripe } from '@/lib/stripe'
import { client } from '@/lib/sanity'
import { resend, FROM } from '@/lib/resend'

export const runtime = 'nodejs'

export async function POST(req: Request) {
  const body = await req.text()
  const sig = req.headers.get('stripe-signature')!
  let event
  try {
    event = stripe.webhooks.constructEvent(body, sig, process.env.STRIPE_WEBHOOK_SECRET!)
  } catch {
    return new Response('Invalid signature', { status: 400 })
  }

  if (event.type === 'checkout.session.completed') {
    const s = event.data.object
    const m = s.metadata

    await client.create({
      _type: 'booking', status: 'confirmed',
      destination: m.destination, slug: m.slug, stayId: m.stayId,
      checkIn: m.checkIn, checkOut: m.checkOut, nights: Number(m.nights),
      amountTotal: s.amount_total, currency: s.currency,
      email: s.customer_details?.email, stripeSessionId: s.id,
    })

    await resend.emails.send({
      from: FROM, to: s.customer_details?.email!,
      subject: `Deine Reise: ${m.destination} ✦`,
      html: `<div style="font-family:Georgia,serif;background:#FAF7F2;padding:48px;text-align:center">
        <h1 style="font-weight:300;color:#1A3A52">${m.destination} ist gebucht.</h1>
        <p style="color:#1A3A52;opacity:.7">${m.checkIn} → ${m.checkOut} · ${m.nights} Nächte</p>
        <p style="color:#C9A86A">✦ Ein neuer Stempel wartet auf dich. ✦</p></div>`,
    })
  }
  return NextResponse.json({ received: true })
}
```

**Sanity-Schema `booking`:** Felder wie im Webhook + `status` (confirmed/canceled).

