## `components/PushOptIn.tsx`

```tsx
'use client'
import { useEffect, useState } from 'react'

const b64url = (s: string) => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4)), (c) => c.charCodeAt(0))

export function PushOptIn() {
  const [state, setState] = useState<'idle' | 'on' | 'denied'>('idle')

  useEffect(() => {
    if ('serviceWorker' in window && Notification.permission === 'granted') setState('on')
    if (Notification.permission === 'denied') setState('denied')
  }, [])

  const enable = async () => {
    const perm = await Notification.requestPermission()
    if (perm !== 'granted') return setState('denied')
    const reg = await navigator.serviceWorker.register('/push-sw.js')
    const sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: b64url(process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY!),
    })
    await fetch('/api/push/subscribe', { method: 'POST', body: JSON.stringify(sub) })
    setState('on')
  }

  if (state === 'on') return <span className="font-mono text-xs text-[#8A9B6E]">🔔 Drops aktiviert</span>
  if (state === 'denied') return null
  return (
    <button onClick={enable}
      className="px-5 py-2 rounded-full border border-[#C9A86A]/50 text-[#C9A86A] font-mono text-xs hover:bg-[#C9A86A] hover:text-[#141419] transition-colors">
      🔔 Journal-Drops aufs Gerät
    </button>
  )
}
