            <Image source={{ uri: d.image }} style={{ width: '100%', aspectRatio: 4 / 5, borderRadius: 16 }} />
            <Text className="font-serif text-ocean text-2xl mt-3">{d.name}</Text>
            <Text className="font-mono text-ocean/50 text-xs mt-1">
              {d.country} · {d.duration} · ab €{d.priceFrom}
            </Text>
          </Pressable>
        ))}
      </ScrollView>
    </SafeAreaView>
  )
}
