## `app/api/photobook/route.tsx` — Gating: Plus gratis, sonst €29

```tsx
import { pdf } from '@react-pdf/renderer'
import { auth } from '@clerk/nextjs/server'
import { client } from '@/lib/sanity'
import { stripe } from '@/lib/stripe'
import { VoyaBook } from '@/lib/pdf/VoyaBook'

export const runtime = 'nodejs'
export const maxDuration = 60
const BASE = process.env.NEXT_PUBLIC_BASE_URL!

const QUERY = /* groq */ `
  *[_type=="traveler" && clerkId==$id][0]{
    name, plusStatus,
    "posts": *[_type=="journalPost" && references(^._id)] | order(publishedAt desc)[0...12]{
      title, excerpt, readingTime, "image": mainImage.asset->url },
    "stamps": stamps[]-> { code: countryCode, country: name }
  }`

export async function GET(req: Request) {
  const { userId } = await auth()
  if (!userId) return new Response('Unauthorized', { status: 401 })

  const traveler = await client.fetch(QUERY, { id: userId })
  if (!traveler?.posts?.length) return Response.json({ error: 'Noch keine Stories — schreib eine! ✦' }, { status: 404 })

  const isPlus = traveler.plusStatus === 'active'
  const sessionId = new URL(req.url).searchParams.get('session_id')
  let paid = false
  if (sessionId) {
    const s = await stripe.checkout.sessions.retrieve(sessionId)
    paid = s.payment_status === 'paid' && s.metadata?.book === '1'
  }

  if (!isPlus && !paid) {
    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      line_items: [{ price_data: { currency: 'eur', unit_amount: 2900,
        product_data: { name: `Voya Photo-Book · ${traveler.name}` } }, quantity: 1 }],
      metadata: { book: '1', clerkId: userId },
      success_url: `${BASE}/api/photobook?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${BASE}/profile`,
    })
    return NextResponse.redirect(session.url!)
  }

  const blob = await pdf(<VoyaBook traveler={traveler} />).toBlob()
  return new Response(blob, {
    headers: {
      'Content-Type': 'application/pdf',
      'Content-Disposition': `attachment; filename="voya-book-${traveler.name.toLowerCase()}.pdf"`,
    },
  })
}
```

